command:
$ErrorActionPreference="Stop"
$repo="C:\dev\flyExplorer"
$main="ef9dbf16495e4911c59492ea43eec1a4b0e06bef"
$candidate="ced7886651c7a87806eb91c63614485d73a51ae9"
$branch="work/remote-retry-evidence-20261005"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("remote-retry-evidence-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"
  & python -X utf8 tools\winui\check_python_static.py tools\winui\classify_remote_failure.py tools\winui\remote_evidence_policy.py tools\winui\validate_remote_request.py tests\winui\test_remote_failure_classifier.py tests\winui\test_remote_evidence_policy.py tests\winui\test_remote_request_preflight_contract.py tests\winui\test_remote_windows_task_contract.py
  if($LASTEXITCODE -ne 0){throw "infra Python static check failed"}
  & python -X utf8 -m unittest tests.winui.test_remote_failure_classifier tests.winui.test_remote_evidence_policy tests.winui.test_remote_request_preflight_contract tests.winui.test_remote_windows_task_contract
  if($LASTEXITCODE -ne 0){throw "infra retry/evidence contracts failed"}
  & git diff --check ($main+".."+$candidate)
  if($LASTEXITCODE -ne 0){throw "candidate diff check failed"}
  Write-Host "REMOTE_RETRY_EVIDENCE_PREMERGE_PASS"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
